svg.script:
// This file does double duty, because on a host that serves .html as
// text/plain it is the only document here that runs at all. Clicked, it
// writes v2.html into a blank window. Loaded as open.svg?px=register in a
// hidden frame of that window, it installs the service worker, which the
// written page cannot do itself -- its own container throws on every call
// -- and reports back. The worker then answers that window's frames.

// The UI comes from the repository rather than from the host this file was
// served by: a CDN may hand out a week-old copy of v2.html long after it
// changed, and raw.githubusercontent never does. The copy next to this file
// is the fallback, for a network that blocks raw.
var RAW = 'https://raw.githubusercontent.com/ltorl/knoiren-browser/main/v2.html';

function ui() {
    return fetch(RAW, { cache: 'no-store' }).then(function (r) {
        if (!r.ok) throw new Error('raw.githubusercontent.com answered ' + r.status);
        return r.text();
    }).catch(function () {
        return fetch('./v2.html').then(function (r) {
            if (!r.ok) throw new Error('./v2.html answered ' + r.status);
            return r.text();
        });
    });
}

function launch() {
    // The window is opened first, while the click is still the reason
    // anything is happening; a popup asked for after the fetch is blocked.
    var n = window.open('about:blank', '_blank');
    if (!n) return;
    ui().then(function (text) {
        var d = n.document;
        d.open();
        d.write(text);
        d.close();

    }, function (err) {
        n.document.body.textContent = 'Could not load the browser: ' + ((err && err.message) || err);
    });
}

document.addEventListener("DOMContentLoaded", () => {
    if (!/(?:^|[?&])px=register(?:&|$)/.test(location.search)) {
        document.elementFromPoint(innerWidth / 2, innerHeight / 2)?.click();
        return;
    }

    const tell = (ok, error) => parent.postMessage({ __px: 'registered', ok, error }, location.origin);
    const sw = navigator.serviceWorker;
    if (!sw) return tell(false, 'This browser has no service workers.');

    sw.register('./sw.js', { scope: './' }).then(reg => new Promise((done, fail) => {
        // Wait for a worker that can answer requests.
        const tick = () => {
            const w = reg.installing || reg.waiting || reg.active;
            if (reg.active) return done(reg.active);
            if (w) return w.addEventListener('statechange', tick, { once: true });
            fail(new Error('the worker went away while installing'));
        };
        tick();
    })).then(worker => new Promise(done => {
        // Ask whether it came up. No answer is not an error.
        const t = setTimeout(() => done(true), 8000);
        sw.addEventListener('message', (e) => {
            if (!e.data || e.data.__px !== 'config') return;
            clearTimeout(t);
            done(!!e.data.ok);
        }, { once: true });
        // The relay Settings picked, if the page sent one along; the
        // worker keeps the one it already has otherwise.
        const wisp = new URLSearchParams(location.search).get('wisp');
        worker.postMessage(wisp ? { __px: 'config', wisp } : { __px: 'config' });
    })).then(
        ok => tell(ok, ok ? '' : 'The worker is running but could not load libcurl.js.'),
        e => tell(false, 'Could not start sw.js: ' + ((e && e.message) || e))
    );
});
